{
  "kcs": [
    {
      "canonical_name": "数列极限",
      "aliases": ["ε-N语言"],
      "description": "用ε-N语言严格定义数列收敛的概念。"
    },
    {
      "canonical_name": "函数极限",
      "aliases": ["ε-δ定义"],
      "description": "用ε-δ语言定义函数在某点或无穷远处的趋势。"
    },
    {
      "canonical_name": "两个重要极限",
      "aliases": ["重要极限"],
      "description": "两个在极限计算中常用的经典极限公式。"
    },
    {
      "canonical_name": "无穷小量比较与等价无穷小",
      "aliases": ["无穷小比较", "等价无穷小替换"],
      "description": "定义无穷小量的阶并等价替换化简极限。"
    },
    {
      "canonical_name": "函数的连续性",
      "aliases": ["连续性", "连续函数"],
      "description": "函数值随自变量变化无间断的性质及分类。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["导函数", "微分系数"],
      "description": "函数在某点的瞬时变化率，差商极限。"
    },
    {
      "canonical_name": "基本初等函数导数表",
      "aliases": ["导数公式", "基本导数表"],
      "description": "常见初等函数的导数公式汇总。"
    },
    {
      "canonical_name": "求导法则",
      "aliases": ["四则求导", "链式法则"],
      "description": "四则运算、复合函数与反函数的求导规则。"
    },
    {
      "canonical_name": "高阶导数",
      "aliases": ["高阶导", "n阶导数"],
      "description": "导数的导数，描述函数更高阶的变化率。"
    },
    {
      "canonical_name": "隐函数求导",
      "aliases": ["隐函数导数"],
      "description": "对隐函数方程两边求导解出导数的方法。"
    },
    {
      "canonical_name": "罗尔定理",
      "aliases": ["罗尔中值定理", "Rolle定理"],
      "description": "若函数满足端点值相等则内部存在导数为零的点。"
    },
    {
      "canonical_name": "拉格朗日中值定理",
      "aliases": ["拉格朗日定理", "Lagrange中值定理", "有限增量公式"],
      "description": "函数两点连线斜率等于某点导数值。"
    },
    {
      "canonical_name": "柯西中值定理",
      "aliases": ["柯西定理", "Cauchy中值定理"],
      "description": "推广拉格朗日，两个函数参数形式的中值定理。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hôpital法则", "洛必达定则"],
      "description": "通过分子分母分别求导求解未定式极限。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["Taylor公式", "泰勒展开", "Taylor展开"],
      "description": "用多项式逼近函数，含余项估计误差。"
    },
    {
      "canonical_name": "麦克劳林展开",
      "aliases": ["麦克劳林公式", "Maclaurin展开"],
      "description": "泰勒公式在零点处的特例，常用函数展开式。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["原函数", "反导数"],
      "description": "求导的逆运算，原函数的集合。"
    },
    {
      "canonical_name": "换元积分法",
      "aliases": ["变量代换", "凑微分法", "第一类换元", "第二类换元"],
      "description": "通过变量代换简化被积函数的积分方法。"
    },
    {
      "canonical_name": "分部积分法",
      "aliases": ["分部积分", "integration by parts"],
      "description": "将复杂积分转化为两个函数乘积的积分公式。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["黎曼积分", "definite integral"],
      "description": "黎曼和极限，区间上函数值的累积和。"
    },
    {
      "canonical_name": "牛顿-莱布尼茨公式",
      "aliases": ["微积分基本定理", "Newton-Leibniz公式"],
      "description": "联系定积分与不定积分，用原函数计算定积分。"
    },
    {
      "canonical_name": "定积分的应用",
      "aliases": ["积分应用", "面积体积"],
      "description": "利用定积分求平面面积、旋转体体积等。"
    }
  ],
